const displayName = ($('Webhook').first().json.body.dulcyContractId ? $('Webhook').first().json.body.name : $('Find leads').first().json.contacts[0].display_name) || '';
const company = $('Webhook').first().json.body.company || '';

// Split display name
const nameParts = displayName.trim().split(/\s+/);

const firstName = nameParts[0] || '';
const lastName = nameParts.slice(1).join(' ') || '';

// First word of company
const companyFirstWord = (company.trim().split(/\s+/)[0] || '').toLowerCase();

return [
  {
    json: {
      first_name: firstName,
      last_name: lastName,
      company: companyFirstWord,
    },
  },
];

